        self.fooSem = Semaphore(1)
        self.barSem = Semaphore(0)

    def foo(self, printFoo):
        for _ in range(self.n):
            self.fooSem.acquire()
            printFoo()
            self.barSem.release()

    def bar(self, printBar):
        for _ in range(self.n):
            self.barSem.acquire()
            printBar()
            self.fooSem.release()

