import threading

class FooBar:
    def __init__(self, n):
        self.n = n
        self.fooTurn = True
        self.cond = threading.Condition()

    def foo(self, printFoo):
        for _ in range(self.n):
            with self.cond:
                while not self.fooTurn:
                    self.cond.wait()
                printFoo()
                self.fooTurn = False
                self.cond.notify_all()

    def bar(self, printBar):
        for _ in range(self.n):
            with self.cond:
                while self.fooTurn:
                    self.cond.wait()
                printBar()
                self.fooTurn = True
                self.cond.notify_all()

