#include <condition_variable>
#include <mutex>
class FooBar {
private:
    int n;
    bool fooTurn = true;
    std::mutex mtx;
    std::condition_variable cv;
public:
    FooBar(int n) : n(n) {}
    void foo(function<void()> printFoo) {
        for (int i = 0; i < n; i++) {
            unique_lock<std::mutex> lk(mtx);
            cv.wait(lk, [this] { return fooTurn; });
            printFoo();
            fooTurn = false;
            cv.notify_all();
        }
    }
    void bar(function<void()> printBar) {
        for (int i = 0; i < n; i++) {
            unique_lock<std::mutex> lk(mtx);
            cv.wait(lk, [this] { return !fooTurn; });
            printBar();
            fooTurn = true;
            cv.notify_all();
        }
    }
};

